shellCommands.command:
cd /workspace && cat > next.config.ts <<'EOF'
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig
EOF
cat > lib/products.ts <<'EOF'
import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

// Shared, cached catalog read. Any view that calls this is invalidated
// together when the "products" tag is revalidated.
export async function getProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('hours')

  return getAllProducts()
}
EOF
cat > app/page.tsx <<'EOF'
import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'
    // Mark catalog data stale with stale-while-revalidate semantics: admins
    // keep seeing the current list while fresh data is recomputed in the
    // background on the next request.
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
EOF
npx next build 2>&1 | tail -25
